mapper.select:
SELECT g.id, g.remark, g.create_time as createTime, g.black_user_id as blackUserId, g.host_id as hostId, m.vip, m.nick_name as nickName, r.nick_name as hostName FROM ${dbLive}.live_black g LEFT JOIN ${dbLive}.live_user r ON g.host_id = r.id INNER JOIN ${dbMain}.member_info m ON g.black_user_id = m.id
and host_id = #{hostId} and black_user_id = #{blackUserId}
ORDER BY g.create_time desc

